create function private.mark_tank_adjustment() returns trigger language plpgsql set search_path='' as $$
begin
 if new.tank_capacity is distinct from old.tank_capacity then new.tank_reference:=jsonb_build_object('manual',true,'updatedAt',now(),'referenceLiters',new.tank_capacity);end if;return new;
end $$;
revoke all on function private.mark_tank_adjustment() from public,anon,authenticated;
create trigger mark_tank_adjustment before update of tank_capacity on public.fleets for each row execute function private.mark_tank_adjustment();
commit;
notify pgrst, 'reload schema';
